func TestScheme(t *testing.T) {
	tests := []struct {
		name   string
		scheme Scheme
		want   string
	}{
		{
			name:   "https",
			scheme: HTTPS,
			want:   "https",
		},
		{
			name:   "http",
			scheme: HTTP,
			want:   "http",
		},
	}

	for _, tt := range tests {
		var (
			scheme = tt.scheme
			want   = tt.want
		)

		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, want, scheme.String())
		})
	}
}

func TestLoad(t *testing.T) {
	tests := []struct {
		name     string
		path     string
		wantErr  bool
		expected *Config
	}{
		{
			name:     "defaults",
			path:     "./testdata/config/default.yml",
			expected: Default(),
		},
		{
			name:     "deprecated defaults",
			path:     "./testdata/config/deprecated.yml",
			expected: Default(),
		},
		{
			name: "configured",
			path: "./testdata/config/advanced.yml",
			expected: &Config{
				Log: logConfig{
					Level: "WARN",
					File:  "testLogFile.txt",
				},
				UI: uiConfig{
					Enabled: false,
				},
				Cors: corsConfig{
					Enabled:        true,
					AllowedOrigins: []string{"foo.com"},
				},
				Cache: cacheConfig{
					Memory: memoryCacheConfig{
						Enabled:          true,
						Expiration:       5 * time.Minute,
						EvictionInterval: 1 * time.Minute,
					},
				},
				Server: serverConfig{
					Host:      "127.0.0.1",
					Protocol:  HTTPS,
					HTTPPort:  8081,
					HTTPSPort: 8080,
					GRPCPort:  9001,
					CertFile:  "./testdata/config/ssl_cert.pem",
					CertKey:   "./testdata/config/ssl_key.pem",
				},
				Database: databaseConfig{
					MigrationsPath: "./config/migrations",
					URL:            "postgres://postgres@localhost:5432/flipt?sslmode=disable",
				},
			},
		},
	}

	for _, tt := range tests {
		var (
			path     = tt.path
			wantErr  = tt.wantErr
			expected = tt.expected
		)

		t.Run(tt.name, func(t *testing.T) {
			cfg, err := Load(path)

			if wantErr {
				require.Error(t, err)
				return
			}

			require.NoError(t, err)

			assert.NotNil(t, cfg)
			assert.Equal(t, expected, cfg)
		})
	}
}

func TestValidate(t *testing.T) {
	tests := []struct {
		name       string
		cfg        *Config
		wantErr    bool
		wantErrMsg string
	}{
		{
			name: "https: valid",
			cfg: &Config{
				Server: serverConfig{
					Protocol: HTTPS,
					CertFile: "./testdata/config/ssl_cert.pem",
					CertKey:  "./testdata/config/ssl_key.pem",
				},
			},
		},
		{
			name: "http: valid",
			cfg: &Config{
				Server: serverConfig{
					Protocol: HTTP,
					CertFile: "foo.pem",
					CertKey:  "bar.pem",
				},
			},
		},
		{
			name: "https: empty cert_file path",
			cfg: &Config{
				Server: serverConfig{
					Protocol: HTTPS,
					CertFile: "",
					CertKey:  "./testdata/config/ssl_key.pem",
				},
			},
			wantErr:    true,
			wantErrMsg: "cert_file cannot be empty when using HTTPS",
		},
		{
			name: "https: empty key_file path",
			cfg: &Config{
				Server: serverConfig{
					Protocol: HTTPS,
					CertFile: "./testdata/config/ssl_cert.pem",
					CertKey:  "",
				},
			},
			wantErr:    true,
			wantErrMsg: "cert_key cannot be empty when using HTTPS",
		},
		{
			name: "https: missing cert_file",
			cfg: &Config{
				Server: serverConfig{
					Protocol: HTTPS,
					CertFile: "foo.pem",
					CertKey:  "./testdata/config/ssl_key.pem",
				},
			},
			wantErr:    true,
			wantErrMsg: "cannot find TLS cert_file at \"foo.pem\"",
		},
		{
			name: "https: missing key_file",
			cfg: &Config{
				Server: serverConfig{
					Protocol: HTTPS,
					CertFile: "./testdata/config/ssl_cert.pem",
					CertKey:  "bar.pem",
				},
			},
			wantErr:    true,
			wantErrMsg: "cannot find TLS cert_key at \"bar.pem\"",
		},
	}

	for _, tt := range tests {
		var (
			cfg        = tt.cfg
			wantErr    = tt.wantErr
			wantErrMsg = tt.wantErrMsg
		)

		t.Run(tt.name, func(t *testing.T) {
			err := cfg.validate()

			if wantErr {
				require.Error(t, err)
				assert.EqualError(t, err, wantErrMsg)
				return
			}

			require.NoError(t, err)
		})
	}
}

